import time
import requests
import json


API_URL_SUBMIT = "https://maas-api.antdigital.com/api/v1/services/audio/asr/transcription"
API_URL_QUERY_BASE = "https://maas-api.antdigital.com/api/v1/tasks/"


def main():
    # If no environment variable is configured, please replace the downlink with the Bailian API Key: api_key = "sk-xxx"
    api_key = os.getenv("DASHSCOPE_API_KEY")

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "X-DashScope-Async": "enable"
    }


    payload = {
        "model": "qwen3-asr-flash-filetrans",
        "input": {
            "file_url": "https://dashscope.oss-cn-beijing.aliyuncs.com/audios/welcome.mp3"
        },
        "parameters": {
            "channel_id": [0],
            # "language": "zh",
            "enable_itn": False
